void Studio::runChokeGroupChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    perform(stop);cancelNoteTool();closeCommandPalette();PopupMenu::dismissAllActiveMenus();auto saved=project;auto savedFile=currentFile;auto savedUndo=undoStack,savedRedo=redoStack;auto savedRevision=revision;bool savedDirty=dirty;int savedTrack=selectedTrack;
    project=emptyProject();currentFile={};selectedTrack=7;selectedClip=-1;publish();undoStack.clear();redoStack.clear();auto original=JSON::toString(projectToJson(project));
    check(setChokeGroup(7,1,revision)&&project.tracks[7].chokeGroup==1&&undoStack.size()==1,"source choke membership commits as one Undo");auto grouped=JSON::toString(projectToJson(project));perform(undoAction);check(JSON::toString(projectToJson(project))==original,"Undo restores ungrouped source exactly");perform(redoAction);check(JSON::toString(projectToJson(project))==grouped,"Redo restores source membership");auto count=undoStack.size();check(setChokeGroup(7,1,revision)&&undoStack.size()==count,"unchanged membership avoids redundant history");
    check(!setChokeGroup(7,17,revision)&&!setChokeGroup(7,2,revision-1)&&!setChokeGroup(-1,2,revision)&&JSON::toString(projectToJson(project))==grouped,"invalid or stale group requests retain the project");recording=true;check(!setChokeGroup(7,2,revision),"recording protects choke membership");recording=false;project.tracks[6].isBus=true;publish();check(!setChokeGroup(6,1,revision),"mixer buses cannot join a source group");
    showPane(channelPane);hits.clear();Image image(Image::ARGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);auto hit=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.action==chokeGroupOpen;});check(hit!=hits.end()&&panes[channelPane].bounds.contains(hit->rect),"channel settings expose the group control within panel bounds");snapshot(folder.getChildFile("choke-channel.png"));if(hit!=hits.end()){auto position=hit->rect.getCentre();auto now=Time::getCurrentTime();MouseEvent event(Desktop::getInstance().getMainMouseSource(),position,ModifierKeys(ModifierKeys::leftButtonModifier),1,0,0,0,0,this,this,now,position,now,1,false);mouseDown(event);mouseUp(event);}check(Component::getNumCurrentlyModalComponents()>0,"actual group-control click opens a native menu");PopupMenu::dismissAllActiveMenus();
    lane()={{0,1,60,.8f}};selectedNote=0;selectedNotes={0};hits.clear();paint(g);Rectangle<float> groupRect,noteRect;for(const auto& h:hits){if(h.action==chokeGroupOpen)groupRect=h.rect;if(h.action==noteConditionOpen)noteRect=h.rect;}check(!groupRect.isEmpty()&&!noteRect.isEmpty()&&!groupRect.intersects(noteRect),"group header remains separate from selected-note controls");selectedNote=-1;selectedNotes.clear();lane().clear();
    check(!searchCommands(paletteEntries(),"choke group").empty(),"command search finds source choke membership");auto path=folder.getChildFile("choke-native.pulse");Project read;check(saveProject(project,path).wasOk()&&loadProject(path,read).wasOk()&&read.tracks[7].chokeGroup==1,"native source group saves and reopens");
    auto notes=lane();check(applySynthPreset(factorySynthPresets()[0],7)&&project.tracks[7].chokeGroup==1&&lane()==notes,"sound recall preserves source group membership");perform(undoAction);check(setChokeGroup(7,0,revision)&&project.tracks[7].chokeGroup==0,"Off removes grouping explicitly");
    perform(stop);project=std::move(saved);currentFile=savedFile;undoStack=std::move(savedUndo);redoStack=std::move(savedRedo);revision=savedRevision;dirty=savedDirty;selectedTrack=savedTrack;publish();
}
void Studio::runChokeGroupTransportTick(){
    auto put=[&](const char* key,bool ok){transportResults.getDynamicObject()->setProperty(key,ok);};
    if(transportTicks==9020){perform(stop);project=emptyProject();project.songMode=true;project.loop=false;project.bpm=120;project.delayReturn=0;project.masterSoftClip=false;project.tracks[7].instrument=Instrument::analog;project.tracks[7].synth.sustain=.8f;project.tracks[7].send=0;project.tracks[6].instrument=Instrument::hat;project.tracks[6].volume=0;project.patterns[0].length=4;project.patterns[0].lanes[7]={{0,4,48,.8f}};project.patterns[0].lanes[6]={{1,.1,42,.8f}};Clip source;source.track=7;source.length=4;Clip close=source;close.track=6;project.clips={source,close};selectedTrack=7;selectedClip=-1;publish();undoStack.clear();redoStack.clear();put("nativeChokeGroupSet",setChokeGroup(7,1,revision)&&setChokeGroup(6,1,revision));engine->observedPeak=0;perform(play);}
    if(transportTicks==9025)put("nativeChokeOpenAudio",engine->playing.load()&&engine->masterMeter.load()>.00001f);
    if(transportTicks==9060){put("nativeChokeClosedAudio",engine->playing.load()&&engine->masterMeter.load()<.00001f&&engine->position.load()>1);perform(stop);auto file=transportReport.getSiblingFile("native-choke.pulse");Project read;put("nativeChokeSave",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.tracks[6].chokeGroup==1&&read.tracks[7].chokeGroup==1);perform(undoAction);put("nativeChokeUndo",project.tracks[6].chokeGroup==0&&project.tracks[7].chokeGroup==1);perform(redoAction);showChokeGroup();put("nativeChokeMenu",Component::getNumCurrentlyModalComponents()>0);snapshot(transportReport.getSiblingFile("native-choke.png"));PopupMenu::dismissAllActiveMenus();}
}
